import { DatabaseSync } from "node:sqlite";

export interface Board {
  id: number;
  name: string;
}

export interface Card {
  id: number;
  boardId: number;
  content: string;
}

export const db = new DatabaseSync(":memory:");
db.exec(`
  CREATE TABLE IF NOT EXISTS boards (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS cards (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    boardId INTEGER NOT NULL,
    content TEXT NOT NULL,
    FOREIGN KEY (boardId) REFERENCES boards(id)
  );
`);

export function createBoard(name: string): void {
  db.prepare(`INSERT INTO boards (name) VALUES (?)`).run(name);
}

export function getBoards(): Board[] {
  return db.prepare(`SELECT * FROM boards`).all() as unknown as Board[];
}

export function createCard(boardId: number, content: string): void {
  db.prepare(`INSERT INTO cards (boardId, content) VALUES (?, ?)`).run(boardId, content);
}

export function getCardsByBoardId(boardId: number): Card[] {
  return db.prepare(`SELECT * FROM cards WHERE boardId = ?`).all(boardId) as unknown as Card[];
}

