export function AdminProductPanel(): JSX.Element {
  const [products, setProducts] = useState<Product[]>([]);
  const [name, setName] = useState<string>("");
  const [description, setDescription] = useState<string>("");
  const [price, setPrice] = useState<number>(0);

  useEffect(() => {
    fetch("/api/catalog-api/products")
      .then(response => response.json())
      .then(data => setProducts(data));
  }, []);

  const handleAddProduct = async () => {
    const newProduct = { name, description, price };
    await fetch("/api/catalog-api/products", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newProduct),
    });
    setProducts([...products, newProduct]);
    setName("");
    setDescription("");
    setPrice(0);
  };

  const handleEditProduct = async (id: number) => {
    // Placeholder for editing product logic
  };

  const handleDeleteProduct = async (id: number) => {
    await fetch(`/api/catalog-api/products/${id}`, { method: "DELETE" });
    setProducts(products.filter(product => product.id !== id));
  };

  return (
    <div>
      <h1>Admin Product Panel</h1>
      <input
        type="text"
        placeholder="Name"
        value={name}
        onChange={(e) => setName(e.target.value)}
      />
      <textarea
        placeholder="Description"
        value={description}
        onChange={(e) => setDescription(e.target.value)}
      />
      <input
        type="number"
        placeholder="Price"
        value={price}
        onChange={(e) => setPrice(Number(e.target.value))}
      />
      <button onClick={handleAddProduct}>Add Product</button>
      <ul>
        {products.map(product => (
          <li key={product.id}>
            {product.name} - ${product.price.toFixed(2)}
            <button onClick={() => handleEditProduct(product.id)}>Edit</button>
            <button onClick={() => handleDeleteProduct(product.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

