  warehouseId: number;
  value: number;
  timestamp: number;
}

export const db = new DatabaseSync(":memory:");
db.exec(`
  CREATE TABLE IF NOT EXISTS readings (
    sensorId INTEGER,
    warehouseId INTEGER,
    value REAL,
    timestamp INTEGER
  );
`);

export function insertReading(sensorId: number, warehouseId: number, value: number, timestamp: number): void {
  db.prepare(`INSERT INTO readings (sensorId, warehouseId, value, timestamp) VALUES (?, ?, ?, ?)`).run(sensorId, warehouseId, value, timestamp);
