}

export function SessionNotesEditor(): JSX.Element {
  const [noteContent, setNoteContent] = useState<string>("");
  const [sessionNotes, setSessionNotes] = useState<Note[]>([]);

  const handleNoteChange = (event: React.ChangeEvent<HTMLTextAreaElement>): void => {
    setNoteContent(event.target.value);
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>): Promise<void> => {
    event.preventDefault();
    try {
      const response = await fetch("/api/sessions-api/sessions/:id/notes", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ content: noteContent }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const newNote: Note = await response.json();
      setSessionNotes([...sessionNotes, newNote]);
      setNoteContent("");
    } catch (error) {
      console.error("Error submitting note:", error);
    }
  };

  return (
    <div>
      <h1>Session Notes Editor</h1>
      <form onSubmit={handleSubmit}>
        <textarea
          value={noteContent}
          onChange={handleNoteChange}
          placeholder="Enter your notes here..."
        />
        <button type="submit">Submit Note</button>
      </form>
      <ul>
        {sessionNotes.map((note: Note) => (
          <li key={note.id}>{note.content}</li>
        ))}
      </ul>
    </div>
  );
}

